 76→export function MessageBubble({ message, messageIndex }: { message: ChatMessage; messageIndex: number }) {
 77→  const { isStreaming, editMessage, deleteMessage } = useAgent();
 78→  const [isEditing, setIsEditing] = useState(false);
 79→  const [editText, setEditText] = useState(message.content);
 80→  const [isConfirmingDelete, setIsConfirmingDelete] = useState(false);
 81→  const textareaRef = useRef<HTMLTextAreaElement>(null);
 82→
 83→  const isUser = message.role === 'user';
 84→  const hasSegments = !isUser && message.segments && message.segments.length > 0;
 85→
 86→  useEffect(() => {
 87→    if (isEditing && textareaRef.current) {
 88→      textareaRef.current.focus();
 89→      textareaRef.current.selectionStart = textareaRef.current.value.length;
 90→    }
 91→  }, [isEditing]);
 92→
 93→  const handleEdit = () => {
 94→    setEditText(message.content);
 95→    setIsEditing(true);
 96→    setIsConfirmingDelete(false);
 97→  };
 98→
 99→  const handleCancelEdit = () => {
100→    setIsEditing(false);
101→    setEditText(message.content);
102→  };
103→
104→  const handleSaveEdit = () => {
105→    const trimmed = editText.trim();
106→    if (!trimmed || trimmed === message.content) {
107→      handleCancelEdit();
108→      return;
109→    }
110→    setIsEditing(false);
111→    editMessage(messageIndex, trimmed);
112→  };
113→
114→  const handleDeleteConfirm = () => {
115→    setIsConfirmingDelete(false);
116→    deleteMessage(messageIndex);
117→  };
118→
119→  const handleKeyDown = (e: React.KeyboardEvent) => {
120→    if (e.key === 'Escape') {
121→      handleCancelEdit();
122→    } else if (e.key === 'Enter' && !e.shiftKey) {
123→      e.preventDefault();
124→      handleSaveEdit();
125→    }
126→  };
127→
128→  let streamingRemainder: string | undefined;
129→  if (hasSegments && message.isStreaming && message.content) {
130→    const segmentedText = message.segments!
131→      .filter((s) => s.type !== 'tool')
132→      .map((s) => s.text || '')
133→      .join('');
134→    const remaining = message.content.slice(segmentedText.length);
135→    if (remaining.trim()) {
136→      streamingRemainder = remaining;
137→    }
138→  }
139→
140→  const hasAnswer = hasSegments && message.segments!.some((s) => s.type === 'answer');
141→  const isInAnswerPhase = message.currentPhase === 'answer';
142→  const isThinkingPhase = !!message.isStreaming && !hasAnswer && !isInAnswerPhase;
143→
144→  const answerSegments = hasSegments
145→    ? message.segments!.filter((s) => s.type === 'answer' && s.text?.trim())
146→    : [];
147→
148→  return (
149→    <div className={`message-bubble message-bubble--${message.role}`}>
150→      <div className="message-bubble__header">

