  margin-right: 32px;
}

.message-bubble__header {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  font-weight: 600;
  color: #6b7280;
  margin-bottom: 4px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.message-bubble__content {
  font-size: 14px;
  line-height: 1.5;
  color: #1f2937;
}

.message-bubble__content p {
  margin: 0 0 8px;
}

.message-bubble__content p:last-child {
  margin-bottom: 0;
}

.message-bubble__content pre {
  background: #f3f4f6;
  padding: 8px 12px;
  border-radius: 6px;
  overflow-x: auto;
  font-size: 12px;
}

.message-bubble__content code {
  background: #f3f4f6;
  padding: 1px 4px;
  border-radius: 3px;
  font-size: 13px;
}

.message-bubble__content pre code {
  background: none;
  padding: 0;
}

.message-bubble__content table {
  border-collapse: collapse;
  width: 100%;
  margin: 8px 0;
  font-size: 13px;
  overflow-x: auto;
  display: block;
}

.message-bubble__content th,
.message-bubble__content td {
  border: 1px solid #d1d5db;
  padding: 6px 10px;
