.message-bubble__segment-content code {
  background: #f3f4f6;
  padding: 1px 4px;
  border-radius: 3px;
  font-size: 13px;
}

.message-bubble__segment-content pre code {
  background: none;
  padding: 0;
}

.message-bubble__segment-content table {
  border-collapse: collapse;
  width: 100%;
  margin: 8px 0;
  font-size: 13px;
  overflow-x: auto;
  display: block;
