  background: #fee2e2;
  color: #dc2626;
}

/* Edit mode */
.message-bubble__edit-mode {
  margin-top: 4px;
}

.message-bubble__edit-textarea {
  width: 100%;
  padding: 8px 10px;
  border: 1px solid #c7d2fe;
